	public bool SwitchTalkStateMine(global::OpcState.OnlineState state, global::OpcController controller) {
		int stationIndex = controller._CharaData.stationIndex;
		int sexId = unionOpcManager.GetSexId(stationIndex);
		isMultiMatchWait = ((UnionOpcController)controller).GetIsMultiMatchWait();
		CreateTalkData();
		systemController.SetIsRecruiment(false);
		// halfword jump table @03d5a256 over state - 3
		switch (state)
		{
			case OpcState.OnlineState.RECRUITMENT_BATTLE:
				if (isMultiMatchWait)
				{
					// written out in the source (no SendRequestBattleRule flag test here, @019eb960)
					NetRequestData requestData = new NetRequestData();
					requestData.data.RequestDataID = NetDataBattleTypeData.DataID;
					requestData.SendReliableData(stationIndex);
					UnionWork.SetTargetOpcState(OpcState.OnlineState.RECRUITMENT_BATTLE);
					return true;
				}
				systemController.SetOnlinePlayerSelectState(OpcState.OnlineState.NOW_BATTLE_UNION);
				systemController.SetFadeAfterSelectState(OpcState.OnlineState.NOW_BATTLE_UNION);
				ChangeTalkData(TalkState.CHECK, stationIndex);
				SendSpokenData(stationIndex);
				transitionController.ResetBattleMachingReceiveData();
				MessageEndSpokenData();
				return true;
			case OpcState.OnlineState.RECRUITMENT_TRADE:
				if (systemController.CheckErrorMessageTrade())
					return false;
				systemController.SetOnlinePlayerSelectState(OpcState.OnlineState.NOW_TRADE);
				systemController.SetFadeAfterSelectState(OpcState.OnlineState.NOW_TRADE);
				systemController.SetTargetStationIndex(stationIndex, unionOpcManager.GetOpc(stationIndex)._CharaData.cassetVersion, true);
				MessageEndSpokenData();
				return true;
			case OpcState.OnlineState.RECRUITMENT_RECORD:
				if (isMultiMatchWait)
				{
					UnionWork.SetTargetOpcState(OpcState.OnlineState.RECRUITMENT_RECORD);
					ShowJoinRecodeCheck(stationIndex);
					return true;
				}
				systemController.SetOnlinePlayerSelectState(OpcState.OnlineState.NOW_RECORD);
				systemController.SetFadeAfterSelectState(OpcState.OnlineState.NOW_RECORD);
				systemController.SetTargetStationIndex(stationIndex, unionOpcManager.GetOpc(stationIndex)._CharaData.cassetVersion, true);
				MessageEndSpokenData();
				return true;
			case OpcState.OnlineState.RECRUITMENT_GREETINGS:
				systemController.SetSystemMessageGreeting();
				systemController.SetOnlinePlayerSelectState(OpcState.OnlineState.NOW_GREETINGS);
				systemController.SetFadeAfterSelectState(OpcState.OnlineState.NOW_GREETINGS);
				systemController.OpenSystemMsgWindow(0, UnionTextData.SpeakerID.SYSTEM);
				systemController.unionMsgSystemWindow.GetNowMessage().inputCloseEnabled = true;
				ChangeTalkData(TalkState.CHECK, stationIndex);
				SendSpokenData(stationIndex);
				systemController.contextMenu = unionContextMenu;
				systemController.SetOnlinePlayerCharacter(playerCharacter);
				systemController.SetTargetStationIndex(stationIndex, unionOpcManager.GetOpc(stationIndex)._CharaData.cassetVersion, true);
				systemController.ChangeOpcState(OpcState.OnlineState.COMMUNICATE);
				systemController.SetEndSpokeEndData(ChangeJoinGreetings);
				systemController.unionMsgSystemWindow.GetNowMessage().inputEnabled = false;
				systemController.unionMsgSystemWindow.GetNowMessage().onFinishedShowAllMessage = systemController.RusultGreetJoinYesNoWindow;
				return true;
			case OpcState.OnlineState.RECRUITMENT_BALL_DECORATION:
				if (!systemController.CheckBallDeco())
					return false;
				systemController.SetSystemMessageBallDeco();
				systemController.SetOnlinePlayerSelectState(OpcState.OnlineState.NOW_BALL_DECORATION);
				systemController.SetFadeAfterSelectState(OpcState.OnlineState.NOW_BALL_DECORATION);
				systemController.SetTargetStationIndex(stationIndex, unionOpcManager.GetOpc(stationIndex)._CharaData.cassetVersion, true);
				MessageEndSpokenData();
				return true;
			case OpcState.OnlineState.COMMUNICATE:
