				systemController.OpenSystemMsgWindow(sexId, UnionTextData.SpeakerID.SYSTEM);
				systemController.unionMsgSystemWindow.GetNowMessage().onFinishedShowAllMessage = () => StartAutoCloseMsgWindow();
				return false;
			case OpcState.OnlineState.NOW_RECORD:
				if (IsMsgWindowOpen())
					return false;
				systemController.SetSystemMessageNowRecord();
				systemController.SetTargetStationIndex(stationIndex, unionOpcManager.GetOpc(stationIndex)._CharaData.cassetVersion, true);
				systemController.OpenSystemMsgWindow(sexId, UnionTextData.SpeakerID.SYSTEM);
				systemController.unionMsgSystemWindow.GetNowMessage().onFinishedShowAllMessage = () => StartAutoCloseMsgWindow();
