	private void StartAutoCloseMsgWindow() {
		systemController.SetTargetStationIndex(-1, -1, true);
		_autoCloseMsgWindowProgressTime = 0.0f;
		Sequencer.update -= UpdateAutoCloseMsgWindow;
		Sequencer.update += UpdateAutoCloseMsgWindow;
	}
	private void CompleteAutoCloseMsgWindow() {
		Sequencer.update -= UpdateAutoCloseMsgWindow;
		systemController.unionMsgSystemWindow.CloseWindow();
		PlayerWork.isPlayerInputActive = true;
	}
	private void UpdateAutoCloseMsgWindow(float deltaTime) {
		if (IsMsgWindowOpen())
		{
			_autoCloseMsgWindowProgressTime += deltaTime;
			if (_autoCloseMsgWindowProgressTime < autoCloseMsgWindowTime)
				return;
		}
		CompleteAutoCloseMsgWindow();
	}
	public void SwitchSpokenStateMine(int index, global::Dpr.NetworkUtils.TalkState talkState) {
		OpcController opc = unionOpcManager.GetOpc(index);
		int cassetVersion = opc._CharaData.cassetVersion;
		if (talkState != TalkState.CHECK)
		{
			int sexId = opc._CharaData.sexId;
			transitionController.ResetBattleMachingReceiveData();
			systemController.StartOpenGreetingMsgWindow(index, sexId, cassetVersion);
			return;
		}
		systemController.OpenSystemMsgWindow(1, UnionTextData.SpeakerID.SYSTEM);
		systemController.unionMsgSystemWindow.GetNowMessage().showLoadingIcon = true;
		systemController.SetTargetStationIndex(index, cassetVersion, true);
	}
	public void SwitchCancelEnd() {
		if (_currentModel == null)
			return;

		if (!_currentModel.isTalkStateEnd)
		{
			_currentModel.OpenSwitchCancelMsg(true);
			return;
		}

		playerCharacter.SetOpcOnlineState(OpcState.OnlineState.NONE);
		var stateData = new NetCharacterStateData();
		stateData.data.isRecruiment = 0;
		stateData.data.state = (byte)playerCharacter.opcState.GetOnlineState();
		stateData.SendReliableDataToAll();
		PlayerWork.isPlayerInputActive = true;
		UnionWork.SetIsTalk(false);
	}
