	public void SwitchTransitionAfterTalk(global::OpcState.OnlineState state, global::OpcController controller) {
		int sexId = unionOpcManager.GetSexId(controller._CharaData.stationIndex);
		// byte jump table @03d5a2c8 over state - 3
		switch (state)
		{
			case OpcState.OnlineState.RECRUITMENT_BATTLE:
			case OpcState.OnlineState.NOW_BATTLE_UNION:
				systemController.OpenMessageTalkBattle(sexId);
				systemController.unionMsgSystemWindow.GetNowMessage().inputCloseEnabled = true;
				break;
			case OpcState.OnlineState.RECRUITMENT_TRADE:
			case OpcState.OnlineState.NOW_TRADE:
				systemController.OpenMessageTalkTrade(sexId);
				break;
			case OpcState.OnlineState.RECRUITMENT_RECORD:
			case OpcState.OnlineState.NOW_RECORD:
				systemController.OpenMessageTalkRecode(sexId);
				break;
			case OpcState.OnlineState.RECRUITMENT_GREETINGS:
			case OpcState.OnlineState.NOW_GREETINGS:
				systemController.OpenMessageTalkGreeting(sexId);
				break;
			case OpcState.OnlineState.RECRUITMENT_BALL_DECORATION:
			case OpcState.OnlineState.NOW_BALL_DECORATION:
				systemController.OpenMessageTalkBallDeco(sexId);
				break;
		}
	}
