	private global::OpcState.OnlineState GetSelectMenuOpcState(int id) {
		// @019f0cc0: (uint)id <= 4 → id + 3
		switch (id)
		{
			case 0:
				return OpcState.OnlineState.RECRUITMENT_BATTLE;
			case 1:
				return OpcState.OnlineState.RECRUITMENT_TRADE;
			case 2:
				return OpcState.OnlineState.RECRUITMENT_RECORD;
			case 3:
				return OpcState.OnlineState.RECRUITMENT_GREETINGS;
			case 4:
				return OpcState.OnlineState.RECRUITMENT_BALL_DECORATION;
			default:
				return OpcState.OnlineState.NONE;
		}
	}
