	public void ShowBattleJoinYesNoMenu(int staIndex) {
		BattleMsgWindow.OpenMsgWindow(0, UnionTextData.SpeakerID.SYSTEM);
		unionBattleContextMenu = new UnionBattleContextMenu();
		BattleMsgWindow.GetNowMessage().onFinishedShowAllMessage = () => unionBattleContextMenu.ShowBattleJoinOtherYesNoWindow(staIndex, Decide, Cancel);
	}
	public void Decide(int stationIndex) {
		if (unionBattleContextMenu != null)
			unionBattleContextMenu.Clear();
		if (unionBattleRuleWindow != null)
			unionBattleRuleWindow.Hide();
		if (BattleMsgWindow != null && transitionController != null && systemController != null)
		{
			systemController.SetOnlinePlayerSelectState(OpcState.OnlineState.RECRUITMENT_BATTLE);
			systemController.SetFadeAfterSelectState(OpcState.OnlineState.RECRUITMENT_BATTLE);
			BattleMsgWindow.OpenMsgWindow(9, UnionTextData.SpeakerID.SYSTEM);
			BattleMsgWindow.GetNowMessage().onFinishedShowAllMessage = transitionController.StartFadeOut;
		}
		UnionWork.SetBattleMode(BattleModeID.Multi);
	}
	public void Cancel() {
		if (unionBattleRuleWindow != null)
			unionBattleRuleWindow.Hide();
		InitPlayerState();
	}
	private void ShowBattleStateWindow(global::System.Collections.Generic.List<global::Dpr.BattleMatching.UnionMatchWaitData> matchWaitDataList, global::Dpr.NetworkUtils.BattleModeID battleModeId) {
		if (unionBattleRuleWindow != null)
			unionBattleRuleWindow.Show();
		SetBattleStateWindowText(matchWaitDataList, battleModeId);
	}
	public void SwitchBatttleStateTalk(int stationIndex, global::Dpr.NetworkUtils.BattleModeID battleModeID) {
		UnionWork.SetBattleMode(battleModeID);
		if (UnionWork.GetIsRecruiment())
		{
			// the model is held in one register across the three calls (@019eb4b8)
			BattleRecruitmentStateModel model = battleRecruitmentModel;
			model.ChangeBattleRecruitmentState(BattleRecruitmentStateModel.BattleRecruitmentState.BATTLE_RULE_CHECK_MINE);
			CreateRecruitmentBattleCancelModel(stationIndex);
			model.ShowBattleRecruitmentYesNoMenu(stationIndex);
			model.ShowBattleStateWindow(stationIndex, battleModeID);
		}
		else if (isMultiMatchWait)
		{
			SendRequestMatchPlayerListData(stationIndex);
		}
		else
		{
			battleJoinStateModel.ShowBattleJoinYesNoMenu(stationIndex);
			battleJoinStateModel.ShowBattleStateWindow(stationIndex, battleModeID);
		}
	}
	private void ShowJoinRecodeCheck(int targetStationIndex) {
		UnionBaseMsgWindow msgWindow = new UnionBaseMsgWindow();
		// shipped: an unused MsgWindowParam is allocated (@019f0018)
		MsgWindowParam msgWindowParam = new MsgWindowParam();
		int sexId = unionOpcManager.GetSexId(targetStationIndex);
		List<UnionTextData.MsgStringParamData> msgStringParamDatas = new List<UnionTextData.MsgStringParamData>();
		for (int i = 0; i < UnionTextData.UNION_RECODE_TRADE_CHECK_JOIN.Length; i++)
		{
			msgStringParamDatas.Add(new UnionTextData.MsgStringParamData
			{
				labelName = UnionTextData.UNION_RECODE_TRADE_CHECK_JOIN[i],
				msgFileName = "dp_net_communication",
			});
		}
		msgWindow.SetTargetDataMessage(UnionWork.GetMyStationIndex(), sexId, 1);
		msgWindow.SetMessagesData(msgStringParamDatas, false, false);
		msgWindow.OpenMsgWindow(0, UnionTextData.SpeakerID.SYSTEM);
		msgWindow.GetNowMessage().onFinishedShowAllMessage = OpenYesNoWindow;

		void OpenYesNoWindow()
		{
			MsgWindowManager.OpenYesNoMenu(selectIndex =>
			{
				if (selectIndex != 0)
				{
					InitPlayerState();
					return;
				}
				SendRequestMatchPlayerListData(targetStationIndex);
			});
		}
	}
	public void ReciveIsMatchWait(global::Dpr.NetworkUtils.NetDataIsMatchWaitData data) {
		List<OpcController> opcControllers = unionOpcManager.GetOpcControllerList();
		if (opcControllers == null)
			return;

		bool isMatchWait = data.data.isMatchWait == 1;
		for (int i = 0; i < opcControllers.Count; i++)
		{
			if (opcControllers[i] == null)
				continue;
			// shipped: every OPC gets the flag, the sender is not looked at (@019f135c)
			((UnionOpcController)opcControllers[i]).SetIsMultiMatchWait(isMatchWait);
		}
	}
	public void ReciveMatchWaitListData(global::Dpr.NetworkUtils.NetDataStandbyWaitListData data) {
		StandbyData[] standbyDataList = data.data.standbyDataList;
		if (standbyDataList == null)
			return;

		int fromStationIndex = data.FromStationIndex;
		for (int i = 0; i < standbyDataList.Length; i++)
		{
			UnionMatchWaitData waitData = new UnionMatchWaitData();
			if (standbyDataList[i].isAddPlayer == 0)
				continue;
			waitData.myStationIndex = standbyDataList[i].myIndex;
			waitData.langId = (Dpr.Message.MessageEnumData.MsgLangId)standbyDataList[i].langId;
			if (SingletonMonoBehaviour<NetworkManager>.Instance.IsGamerActive(waitData.myStationIndex))
				waitData.playerName = NetworkManager.GetGamerData(waitData.myStationIndex).gamerName;
			AddMatchWait(waitData);
		}

		if (isMultiMatchWait)
		{
			OpcState.OnlineState targetOpcState = UnionWork.GetTargetOpcState();
			if (targetOpcState == OpcState.OnlineState.RECRUITMENT_RECORD)
			{
				systemController.SetOnlinePlayerSelectState(OpcState.OnlineState.RECRUITMENT_RECORD);
				systemController.SetFadeAfterSelectState(OpcState.OnlineState.RECRUITMENT_RECORD);
				transitionController.StartFadeOut();
				SendAddStanbyPlayer();
			}
			else if (targetOpcState == OpcState.OnlineState.RECRUITMENT_BATTLE)
			{
				BattleModeID battleMode = UnionWork.GetBattleMode();
				ShowBattleJoinYesNoMenu(fromStationIndex);
				ShowBattleStateWindow(unionMatchWaitDataList, battleMode);
			}
		}

		if (transitionController != null && unionMatchWaitDataList != null)
			transitionController.SetStanbyWaitDataList(unionMatchWaitDataList);
	}
	public void ReciveMatchWaitData(global::Dpr.NetworkUtils.NetDataStandbyWaitData data) {
		UnionMatchWaitData waitData = new UnionMatchWaitData();
		if (data.data.isAddPlayer == 0)
			return;
		waitData.myStationIndex = data.data.myIndex;
		waitData.langId = (Dpr.Message.MessageEnumData.MsgLangId)data.data.langId;
		if (SingletonMonoBehaviour<NetworkManager>.Instance.IsGamerActive(waitData.myStationIndex))
			waitData.playerName = NetworkManager.GetGamerData(waitData.myStationIndex).gamerName;
		AddMatchWait(waitData);
		transitionController.AddStanbyData(waitData);
	}
	private void AddMacthPlayerData(int targetStationIndex) {
		UnionMatchWaitData waitData = new UnionMatchWaitData();
		waitData.myStationIndex = targetStationIndex;
		waitData.langId = (Dpr.Message.MessageEnumData.MsgLangId)NetworkManager.GetGamerData(targetStationIndex).nameStringLanguage;
		AddMatchWait(waitData);
		if (transitionController != null)
			transitionController.AddStanbyData(waitData);
		// shipped: the own station index is fetched and never used (@019f1a10)
		int myStationIndex = SingletonMonoBehaviour<NetworkManager>.Instance.MyStationIndex;
		SendAddStanbyPlayer();
	}
	private void AddMacthPlayerDataInMine(int hostIndex, int joinPlayerIndex, int sendTargetIndex) {
		UnionMatchWaitData hostData = new UnionMatchWaitData();
		hostData.myStationIndex = hostIndex;
		hostData.langId = (Dpr.Message.MessageEnumData.MsgLangId)NetworkManager.GetGamerData(hostIndex).nameStringLanguage;
		UnionMatchWaitData joinData = new UnionMatchWaitData();
		joinData.myStationIndex = joinPlayerIndex;
		// shipped bug: the joiner's language is written to the HOST entry (`str w8, [x21, #0x20]` @019f1af8), joinData.langId stays default
		hostData.langId = (Dpr.Message.MessageEnumData.MsgLangId)NetworkManager.GetGamerData(joinPlayerIndex).nameStringLanguage;
		AddMatchWait(hostData);
		AddMatchWait(joinData);
		if (transitionController != null && unionMatchWaitDataList != null)
			transitionController.SetStanbyWaitDataList(unionMatchWaitDataList);
		SendStandbyPlayerData(sendTargetIndex);
	}
	public void AddMatchWait(global::Dpr.BattleMatching.UnionMatchWaitData waitData) {
		unionMatchWaitDataList.Add(waitData);
	}
	public void RemoveMatchWait(int removeIndex) {
		unionMatchWaitDataList.RemoveAt(removeIndex);
		transitionController.SetStanbyWaitDataList(unionMatchWaitDataList);
	}
	public void RemoveMatchWaitStationIndex(int stationIndex) {
		for (int i = 0; i < unionMatchWaitDataList.Count; i++)
		{
			if (unionMatchWaitDataList[i] == null)
				continue;
			if (unionMatchWaitDataList[i].myStationIndex == stationIndex)
			{
				RemoveMatchWait(i);
				return;
			}
		}
	}
	public void ClearMatchWait() {
		unionMatchWaitDataList.Clear();
	}
	public global::System.Collections.Generic.List<global::Dpr.BattleMatching.UnionMatchWaitData> GetMatchWaitList() {
		return unionMatchWaitDataList;
	}
	private void SendRequestIsMatchWait(int stationIndex) {
		NetRequestData requestData = new NetRequestData();
		requestData.data.RequestDataID = NetDataIsMatchWaitData.DataID;
		requestData.SendReliableData(stationIndex);
	}
	private void SendRequestMatchPlayerListData(int stationIndex) {
		NetRequestData requestData = new NetRequestData();
		requestData.data.RequestDataID = NetDataStandbyWaitListData.DataID;
		requestData.SendReliableData(stationIndex);
	}
	private void SendRequestBattleRule(int stationIndex) {
		NetRequestData requestData = new NetRequestData();
		requestData.data.RequestDataID = NetDataBattleTypeData.DataID;
		requestData.SendReliableData(stationIndex);
	}
	private void SendIsMatchWait() {
		NetDataIsMatchWaitData matchWaitData = new NetDataIsMatchWaitData();
		matchWaitData.data.isMatchWait = 0;
		matchWaitData.SendReliableDataToAll();
	}
	private void SendAddStanbyPlayer() {
		int myStationIndex = UnionWork.GetMyStationIndex();
		NetDataStandbyWaitData standbyWaitData = new NetDataStandbyWaitData();
		standbyWaitData.data.myIndex = (byte)myStationIndex;
		standbyWaitData.data.langId = (byte)PlayerWork.msgLangID;
		standbyWaitData.data.isAddPlayer = 1;
		// the list is read once (@019f17f8)
		List<UnionMatchWaitData> matchWaitDataList = unionMatchWaitDataList;
		for (int i = 0; i < matchWaitDataList.Count; i++)
			standbyWaitData.SendReliableData(matchWaitDataList[i].myStationIndex);
	}
	private void SendRecodeData(global::DPData.RECORD recodeData, int targetStationIndex) {
		NetDataRecodeData netDataRecode = new NetDataRecodeData();
		netDataRecode.data.myVersion = (byte)PlayerWork.cassetVersion;
		netDataRecode.data.recodeData = recodeData;
		netDataRecode.data.randomSeed = PlayerWork.RandomGroup.group[0];
		TvWork.RecordData recordData = TvWork.CreateRecordData();
		if (recordData.Personality != null)
		{
			netDataRecode.data.PersonalityIsNotEmpty = 1;
			netDataRecode.data.PersonalityBranchData = recordData.Personality.BranchData;
			netDataRecode.data.PersonalityPlayerName = recordData.Personality.PlayerName;
		}
		if (recordData.BallDecoration != null)
		{
			netDataRecode.data.BallDecorationIsNotEmpty = 1;
			netDataRecode.data.BallDecorationBranchData = recordData.BallDecoration.BranchData;
			netDataRecode.data.Trainer = recordData.BallDecoration.Trainer;
		}
		if (recordData.Kasekihori != null)
		{
			netDataRecode.data.KasekihoriIsNotEmpty = 1;
			netDataRecode.data.KasekihoriBranchData = recordData.Kasekihori.BranchData;
			netDataRecode.data.ItemNo = recordData.Kasekihori.ItemNo;
			netDataRecode.data.KasekihoriPlayerName = recordData.Kasekihori.PlayerName;
		}
		if (recordData.Statue != null)
		{
			netDataRecode.data.StatueIsNotEmpty = 1;
			netDataRecode.data.StatueBranchData = recordData.Statue.BranchData;
			netDataRecode.data.StatueCount = recordData.Statue.StatueCount;
			netDataRecode.data.StatuePlayerName = recordData.Statue.PlayerName;
		}
		if (recordData.Fashion != null)
		{
			// shipped: FashionPlayerName is never copied (@019f2214–f223c)
			netDataRecode.data.FashionIsNotEmpty = 1;
			netDataRecode.data.FashionBranchData = recordData.Fashion.BranchData;
			netDataRecode.data.PlaceNo = recordData.Fashion.PlaceNo;
			netDataRecode.data.Style = recordData.Fashion.Style;
		}
		netDataRecode.SendReliableData(targetStationIndex);
	}
	private void SendStandbyPlayerData(int stationIndex) {
		// the list is read once (@019f1bf0)
		List<UnionMatchWaitData> matchWaitDataList = unionMatchWaitDataList;
		if (matchWaitDataList == null)
			return;

		NetDataStandbyWaitListData standbyWaitListData = new NetDataStandbyWaitListData();
		StandbyData[] standbyDatas = new StandbyData[5];
		for (int i = 0; i < matchWaitDataList.Count; i++)
		{
			if (matchWaitDataList[i] == null)
				continue;
			standbyDatas[i] = new StandbyData
			{
				isAddPlayer = 1,
				myIndex = (byte)matchWaitDataList[i].myStationIndex,
				langId = (byte)matchWaitDataList[i].langId,
			};
		}
		standbyWaitListData.data.standbyDataList = standbyDatas;
		standbyWaitListData.SendReliableData(stationIndex);
	}
	private void ClearMatchPlayerDataList() {
		UnionWork.SetIsTalk(false);
		InitPlayerState();
		SendIsMatchWait();
		PlayerWork.isPlayerInputActive = true;
		systemController.SetTargetStationIndex(-1, -1, true);
		unionMatchWaitDataList.Clear();
	}
}
